import{_ as r,l as i,o as e,c as s,v as t,p as c,x as n,d as l,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const q=JSON.parse('{"title":"生产基础的资产定价","description":"","frontmatter":{"title":"生产基础的资产定价","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/production-based-asset-pricing.md","filePath":"econ/production-based-asset-pricing.md","lastUpdated":1789023840000}'),m={name:"econ/production-based-asset-pricing.md"};function h(u,a,E,_,A,f){const o=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="生产基础的资产定价" tabindex="-1">生产基础的资产定价 <a class="header-anchor" href="#生产基础的资产定价" aria-label="Permalink to &quot;生产基础的资产定价&quot;">​</a></h1><div class="epigraph"><p>有生产时，投资的一阶条件给资本回报定价；随机折现因子仍可以来自消费者，但股利不再等于果实。</p><footer>—— Cochrane, Production-Based Asset Pricing and the Link Between Stock Returns and Economic Fluctuations, Journal of Finance, 1991</footer></div><p><a href="/econ/term-structure-of-risk">上一课</a>仍在把支付流切开，支付本身在 Lucas 树里等于外生果实。本课缺口是<strong>生产</strong>：企业用资本与投资技术把果实变成内生，\\(c\\) 与股利分家，\\(m\\) 可以同时从家庭欧拉与从投资欧拉读出。不重写树的 \\(p(y)\\)，不把 RBC 校准表搬进来。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>交换经济：\\(c=y\\)，股权是对 \\(y\\) 的要求权。生产经济：产出 \\(f(k)\\)，资本积累 \\(k&#39;= (1-\\delta)k+i\\)，调整成本使投资与 \\(q\\) 有关。企业最大化市场价值，使用同一 \\(m\\) 折现。Cochrane（1991）强调：投资回报（边际上多装一单位资本再拆掉）在最优处被 \\(m\\) 定价，于是资产回报与投资、产出共变——无需先经过消费数据。缺口是给 \\(m\\) 第二条通道：消费太平滑时，投资的波动仍可能给核提供力矩。</p><p>这不是否定家庭欧拉，而是对偶。完全市场下两条欧拉描述同一 \\(m\\)。测量上消费噪、投资也噪，哪一条好用是实证；本栏只完成映射。</p><p><span class="marginnote">Cochrane, <em>Journal of Finance</em> 46(1), 1991。Jermann、Tallarini、Belo 等把调整成本与生产冲击写进定量一般均衡。本课不定量。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>家庭：\\(m=\\beta u&#39;(c&#39;)/u&#39;(c)\\)。企业：投资的边际成本（含调整）等于边际 \\(q\\)；资本的边际产出加价格变化构成投资回报 \\(R^I\\)，满足 \\(1=\\mathrm{E}[m R^I]\\)。若上市公司是资本的要求权，\\(R^I\\) 与股票回报在技术与市场结构的理想情形下对齐。调整成本越凸，投资越平滑，\\(q\\) 越波动——价格波动可以来自安装摩擦，而不只来自 \\(u&#39;(c)\\)。</p>',9)),(e(),c(p,null,{default:n(()=>[d(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20HH%5B%22%E5%AE%B6%E5%BA%AD%E6%AC%A7%E6%8B%89%3A%20m%20%3D%20MRS%22%5D%20--%3E%20M%5B%22%E5%90%8C%E4%B8%80%20m%22%5D%0A%20%20FIR%5B%22%E6%8A%95%E8%B5%84%E6%AC%A7%E6%8B%89%3A%201%20%3D%20E%5Bm%20R%5EI%5D%22%5D%20--%3E%20M%0A%20%20TREE%5B%22Lucas%3A%20c%20%3D%20y%22%5D%20--%3E%20SPLIT%5B%22%E7%94%9F%E4%BA%A7%3A%20c%20%E4%B8%8E%E8%82%A1%E5%88%A9%E5%88%86%E5%AE%B6%22%5D%0A%20%20SPLIT%20--%3E%20M%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与 <a href="/econ/capm-theory">CAPM</a>：生产基础不自动给出市场 beta。只有当投资回报与市场完全相关、加总又回到均值方差时，两条特化重合。一般地，生产冲击是 \\(m\\) 的候选状态，不是 Fama–French 的执照。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是跨期技术替代。今天多投资，明天多资本、少消费（或少股利），最优时两边的边际用同一 \\(m\\) 对齐。果实不再直接等于消费，平滑可以发生在存货、劳动、调整成本上——这正是树解释不了价格波动时的出口之一。风险的期限结构现在可以对准资本的安装周期：短现金流更像当期产出，长现金流更像已安装资本的租金。</p><p>不完全市场或融资约束下，企业的 \\(m\\) 可以变成内部影子价格，与家庭 \\(m\\) 分开——下一课序的中介资产定价从这里起步。本课先保持完全、无摩擦，好让对照干净。</p><p><span class="marginnote">\\(q\\) 理论（Tobin, Hayashi）是投资欧拉的确定版。随机折现把它变成资产定价：边际 \\(q\\) 是资本要求权的价格。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把投资–回报相关写成「所以生产模型赢了消费模型」的赛马。两条欧拉在理论上兼容，数据上可以双双失败。也不要把生产基础写成限价簿：企业 \\(q\\) 不是盘口。本课序「定价的数学骨架」在此收束：从 LOP 到树到会计到生产，无摩擦骨架已经够用。下一课序打开摩擦与中介，\\(m\\) 开始依赖谁的约束在绑紧。</p><p>后课默认：生产经济里投资欧拉与消费欧拉对偶同一 \\(m\\)；\\(c\\) 不必等于股利。融资约束会把企业核与家庭核劈开，那是下一课序。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>投资回报在最优处被 \\(m\\) 定价；生产给核第二条可读的欧拉。</li><li>调整成本让 \\(q\\) 与投资分家，价格波动可来自技术摩擦。</li><li>完全无摩擦时与 Lucas 核兼容；\\(c\\) 与股利不再恒等。</li><li>出处：Cochrane, <em>Journal of Finance</em> 1991；对照 Hayashi 的 \\(q\\)、Jermann。</li></ul>',10))])}const T=r(m,[["render",h]]);export{q as __pageData,T as default};
